def _handle_type_a(item):
    value = item["value"] * 2
    category = "high" if value > 100 else "low"
    return {"id": item["id"], "value": value, "category": category}


def _handle_type_b(item):
    value = item["value"] + 50
    return {"id": item["id"], "value": value, "category": "adjusted"}


def _handle_type_c(item):
    value = item["value"]
    if value < 0:
        return {"id": item["id"], "value": 0, "category": "clamped"}
    return {"id": item["id"], "value": value, "category": "passthrough"}


def _dispatcher(item):
    handlers = {
        "A": _handle_type_a,
        "B": _handle_type_b,
        "C": _handle_type_c,
    }
    handler = handlers.get(item.get("type"))
    if handler:
        return handler(item)
    return None


def process_data(data):
    results = []
    for item in data:
        result = _dispatcher(item)
        if result is not None:
            results.append(result)
    return results
