### Runtime Validation Function

```typescript
function validateUser(user: unknown): user is User {
  if (typeof user !== 'object' || user === null) return false;

  const u = user;

  // id must be an integer (Python `int` → TS `number` with integer check)
  if (typeof u.id !== 'number' || !Number.isInteger(u.id)) return false;

  // name must be a non-empty string
  if (typeof u.name !== 'string' || u.name.length === 0) return false;

  // email must contain "@"
  if (typeof u.email !== 'string' || !u.email.includes('@')) return false;

  // preferences sub-object checks
  if (
    typeof u.preferences?.theme !== 'string' ||
    typeof u.preferences?.notifications !== 'boolean'
  )
    return false;

  // tags must be an array of strings
  if (!Array.isArray(u.tags) || !u.tags.every((t) => typeof t === 'string'))
    return false;

  // last_login must be a string (ISO format observed)
  if (typeof u.last_login !== 'string') return false;

  // metadata: accepts null, undefined, or absent (optional/nullable handling)
  if (u.metadata !== null && u.metadata !== undefined) return false;

  return true;
}
